                else:
                    # Trigger B, now wait for cooldown
                    if cooldown_remaining == 0:
                        # Move to platform to ensure altitude for C
                        if not is_in_zone(current_pos, platform_center, platform_half):
                            move_toward_target(platform_center, current_pos, current_vel)
                        else:
                            # Move to C's zone
                            move_toward_target(zone_c, current_pos, current_vel)
    elif next_sw == 'C':
        if not is_in_zone(current_pos, zone_c, zone_c_half):
            move_toward_target(zone_c, current_pos, current_vel)
        else:
            steps_in_zone = sandbox.get_steps_in_current_zone()
            if steps_in_zone < 25:
                move_toward_target(zone_c, current_pos, current_vel)
            else:
                pass

import math

def build_agent(sandbox):
    return None

a_trigger_step = None
b_trigger_step = None
c_trigger_step = None
y_history = []

def agent_action(sandbox, agent_body, step_count):
    global a_trigger_step, b_trigger_step, c_trigger_step, y_history

    current_pos = sandbox.get_agent_position()
    current_vel = sandbox.get_agent_velocity()
    next_sw = sandbox.get_next_required_switch()

    if next_sw is None:
        return

    def is_in_zone(pos, center, half):
        x, y = pos
        cx, cy = center
        return abs(x - cx) <= half[0] and abs(y - cy) <= half[1]

    def adjust_velocity(current_vel):
        fx = 0.0
        fy = 0.0
        if current_vel[0] > 0.5:
            fx = -10.0
        elif current_vel[0] < -0.5:
            fx = 10.0
        if current_vel[1] > 0.5:
            fy = -10.0
        elif current_vel[1] < -0.5:
            fy = 10.0
        mag = math.hypot(fx, fy)
        if mag > 60.0:
            scale = 60.0 / mag
            fx *= scale
            fy *= scale
        return fx, fy

    if next_sw == 'A':
        target_pos = (2.0, 2.0)
        zone_half = (0.5, 0.5)
        if not is_in_zone(current_pos, target_pos, zone_half):
            dx = target_pos[0] - current_pos[0]
            dy = target_pos[1] - current_pos[1]
            distance = math.hypot(dx, dy)
            if distance > 0.1:
                direction = (dx / distance, dy / distance)
                fx = 50.0 * direction[0]
                fy = 50.0 * direction[1]
                mag = math.hypot(fx, fy)
                if mag > 60.0:
                    scale = 60.0 / mag
                    fx *= scale
                    fy *= scale
                sandbox.apply_agent_force(fx, fy)
        else:
            steps_in_zone = sandbox.get_steps_in_current_zone()
            if steps_in_zone < 25:
                fx, fy = adjust_velocity(current_vel)
                sandbox.apply_agent_force(fx, fy)
            else:
                a_trigger_step = step_count
                next_sw = sandbox.get_next_required_switch()
                if next_sw == 'B':
                    pass
    elif next_sw == 'B':
        if sandbox.get_cooldown_remaining() == 0 and sandbox.get_barrier_delay_steps() == 0:
            if a_trigger_step is not None and (step_count - a_trigger_step) < 160:
                target_pos = (4.95, 3.2)
                zone_half = (0.7, 0.4)
                if not is_in_zone(current_pos, target_pos, zone_half):
                    dx = target_pos[0] - current_pos[0]
                    dy = target_pos[1] - current_pos[1]
